`ifndef XIL_XECLIB
  reg attr_test;
  reg attr_err;
  
  initial begin
  trig_attr = 1'b0;
  `ifdef XIL_ATTR_TEST
    attr_test = 1'b1;
  `else
    attr_test = 1'b0;
  `endif
    attr_err = 1'b0;
    #1;
    trig_attr = ~trig_attr;
  end
`endif

`ifndef XIL_XECLIB
  always @ (trig_attr) begin
    #1;
    if ((attr_test == 1'b1) ||
        ((CDX_MODE_REG != "NONE") &&
         (CDX_MODE_REG != "CDM"))) begin
      $display("Error: [Unisim %s-101] CDX_MODE attribute is set to %s.  Legal values for this attribute are NONE or CDM. Instance: %m", MODULE_NAME, CDX_MODE_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((CPM5N_MPIOBOT_MODE_REG != "NONE") &&
         (CPM5N_MPIOBOT_MODE_REG != "CPM5N_CDX_CXL") &&
         (CPM5N_MPIOBOT_MODE_REG != "CPM5N_DPU") &&
         (CPM5N_MPIOBOT_MODE_REG != "CPM5N_DPU_CDX_HYBRID") &&
         (CPM5N_MPIOBOT_MODE_REG != "CPM5N_PCIE01_CXL"))) begin
      $display("Error: [Unisim %s-102] CPM5N_MPIOBOT_MODE attribute is set to %s.  Legal values for this attribute are NONE, CPM5N_CDX_CXL, CPM5N_DPU, CPM5N_DPU_CDX_HYBRID or CPM5N_PCIE01_CXL. Instance: %m", MODULE_NAME, CPM5N_MPIOBOT_MODE_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((CPM5N_MPIOTOP_MODE_REG != "NONE") &&
         (CPM5N_MPIOTOP_MODE_REG != "CPM5N_CDX_CXL") &&
         (CPM5N_MPIOTOP_MODE_REG != "CPM5N_DPU") &&
         (CPM5N_MPIOTOP_MODE_REG != "CPM5N_DPU_CDX_HYBRID") &&
         (CPM5N_MPIOTOP_MODE_REG != "CPM5N_PCIE23_CXL"))) begin
      $display("Error: [Unisim %s-103] CPM5N_MPIOTOP_MODE attribute is set to %s.  Legal values for this attribute are NONE, CPM5N_CDX_CXL, CPM5N_DPU, CPM5N_DPU_CDX_HYBRID or CPM5N_PCIE23_CXL. Instance: %m", MODULE_NAME, CPM5N_MPIOTOP_MODE_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((DPU_MODE_REG != "NONE") &&
         (DPU_MODE_REG != "CRYPTO_OFF") &&
         (DPU_MODE_REG != "CRYPTO_ON"))) begin
      $display("Error: [Unisim %s-104] DPU_MODE attribute is set to %s.  Legal values for this attribute are NONE, CRYPTO_OFF or CRYPTO_ON. Instance: %m", MODULE_NAME, DPU_MODE_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((LINK_SPEED_0_REG != "GEN2") &&
         (LINK_SPEED_0_REG != "ESM20G") &&
         (LINK_SPEED_0_REG != "ESM25G") &&
         (LINK_SPEED_0_REG != "GEN3") &&
         (LINK_SPEED_0_REG != "GEN4") &&
         (LINK_SPEED_0_REG != "GEN5"))) begin
      $display("Error: [Unisim %s-105] LINK_SPEED_0 attribute is set to %s.  Legal values for this attribute are GEN2, ESM20G, ESM25G, GEN3, GEN4 or GEN5. Instance: %m", MODULE_NAME, LINK_SPEED_0_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((LINK_SPEED_1_REG != "GEN2") &&
         (LINK_SPEED_1_REG != "GEN3") &&
         (LINK_SPEED_1_REG != "GEN4") &&
         (LINK_SPEED_1_REG != "GEN5"))) begin
      $display("Error: [Unisim %s-106] LINK_SPEED_1 attribute is set to %s.  Legal values for this attribute are GEN2, GEN3, GEN4 or GEN5. Instance: %m", MODULE_NAME, LINK_SPEED_1_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((LINK_SPEED_2_REG != "GEN2") &&
         (LINK_SPEED_2_REG != "ESM20G") &&
         (LINK_SPEED_2_REG != "ESM25G") &&
         (LINK_SPEED_2_REG != "GEN3") &&
